// Article implementations use image textures so the same scenes work with user media.
export const objectFit = {
  count: 1,
  layout: ({ aspect }) => ({ w: aspect, h: 1 }),
  // Interpolate the remaining crop margin like CSS object-position.
  fragment: `
    vec2 scale = min(vec2(ratio / ratioA, ratioA / ratio), 1.);
    color = texture2D(mapA, uv * scale + (1. - scale) * mouse);
  `,
};

export const liquidGlassGrid = {
  count: 63,
  layout({ slot, phase, mx, my }) {
    const row = Math.floor(slot / 9);
    const longitude = ((slot % 9) - 4 - phase + (row % 2) / 2 + (mx - .5) * .7) * .238;
    const latitude = (row - 3 + (my - .5) * .8) * .18;
    const radius = 2.1;
    return {
      w: .46, h: .335,
      x: radius * Math.cos(latitude) * Math.sin(longitude),
      y: radius * Math.sin(latitude),
      z: radius * (Math.cos(latitude) * Math.cos(longitude) - 1),
      ry: longitude, rx: -latitude,
    };
  },
  functions: `
    float tileDistance(vec2 p, vec2 extent, float radius) {
      vec2 corner = abs(p) - extent + radius;
      return length(max(corner, 0.)) + min(max(corner.x, corner.y), 0.) - radius;
    }
  `,
  fragment: `
    vec2 extent = vec2(ratio, 1.) * .5;
    vec2 pos = (uv - .5) * 2. * extent;
    float d = tileDistance(pos, extent, .07);
    if (d > 0.) discard;
    vec2 normal = normalize(vec2(
      tileDistance(pos + vec2(.001, 0.), extent, .07) - d,
      tileDistance(pos + vec2(0., .001), extent, .07) - d
    ) + .00001);
    float bevel = exp(22. * d);
    vec2 bend = normal * bevel * .085 / vec2(ratio, 1.);
    color = sampleA(uv - bend);
    color.r = sampleA(uv - bend * 1.08).r;
    color.b = sampleA(uv - bend * .91).b;
    color.rgb += .32 * pow(bevel, 3.) * (.25 + .75 * abs(dot(normal, normalize(vec2(-.6, 1.)))));
    color.a *= 1. - smoothstep(-fwidth(d), 0., d);
  `,
};

export const phantomGrid = {
  count: 63, portrait: true,
  layout({ slot, phase, mx, my, aspect }) {
    const x = ((slot % 9) - 4 - phase) * .42 - (mx - .5) * .09;
    const y = (Math.floor(slot / 9) - 3) * .31 - (my - .5) * .08;
    const dx = x - (mx - .5) * aspect, dy = y - (my - .5);
    const influence = Math.exp(-9 * (dx * dx + dy * dy));
    return { x: x + dx * influence * .5, y: y + dy * influence * .5,
      z: -.2 + .12 * influence, w: .39, h: .285, ry: dx * influence, rx: -dy * influence };
  },
};

// Change the camera and look-at target independently, as in the scroll timeline.
export const cinematicScroll = {
  count: 9,
  layout({ offset, index }) {
    return { x: Math.sin(index * 1.9) * .42, y: Math.cos(index * 1.3) * .18,
      z: -offset * 1.6, w: 1.08, h: .76, ry: Math.sin(index) * .24, visible: offset > -.9 };
  },
  camera(camera, { travel, phase }) {
    const index = Math.floor(travel);
    const ease = phase * phase * (3 - 2 * phase);
    const interpolate = fn => fn(index) * (1 - ease) + fn(index + 1) * ease;
    const targetX = interpolate(i => Math.sin(i * 1.9) * .42);
    const targetY = interpolate(i => Math.cos(i * 1.3) * .18);
    camera.position.set(targetX + .32 * Math.sin(travel * 1.45), targetY + .14 * Math.cos(travel * 1.21), 1.34);
    camera.lookAt(targetX, targetY, -.1);
  },
};

// Position-based cloth. The top edge is pinned and neighboring particles
// preserve their rest lengths. A fixed simulation step makes seeking repeatable.
export function clothGeometry(geometry) {
  const positions = geometry.attributes.position;
  const rest = new Float32Array(positions.array),
    previous = new Float32Array(rest);
  const columns = geometry.parameters.widthSegments + 1;
  const edges = [];
  for (let n = 0; n < positions.count; n++) {
    if (n % columns) edges.push([n - 1, n, 1 / (columns - 1)]);
    if (n >= columns)
      edges.push([n - columns, n, 1 / geometry.parameters.heightSegments]);
  }
  let tick = 0,
    cycle = -1;
  return (time) => {
    const period = 4,
      epoch = Math.floor(time / period);
    const target = Math.floor((time - epoch * period) * 60);
    const a = positions.array;
    if (epoch !== cycle || target < tick) {
      a.set(rest);
      previous.set(rest);
      tick = 0;
      cycle = epoch;
    }
    while (tick < target) {
      tick++;
      for (let n = columns; n < positions.count; n++) {
        const i = n * 3;
        const wind =
          0.0014 * Math.sin(rest[i] * 5 + tick / 18) +
          0.0007 * Math.cos(rest[i + 1] * 6 - tick / 17);
        for (let j = 0; j < 3; j++) {
          const x = a[i + j];
          a[i + j] +=
            (x - previous[i + j]) * 0.981 +
            (j === 2 ? wind : j === 1 ? -0.0011 : 0.00015);
          previous[i + j] = x;
        }
      }
      for (let pass = 0; pass < 4; pass++)
        for (const [m, n, length] of edges) {
          const i = m * 3,
            j = n * 3,
            dx = a[j] - a[i],
            dy = a[j + 1] - a[i + 1],
            dz = a[j + 2] - a[i + 2];
          const distance = Math.hypot(dx, dy, dz) || length;
          const factor = (1 - length / distance) / (m < columns ? 1 : 2);
          if (m >= columns) {
            a[i] += dx * factor;
            a[i + 1] += dy * factor;
            a[i + 2] += dz * factor;
          }
          if (n >= columns) {
            a[j] -= dx * factor;
            a[j + 1] -= dy * factor;
            a[j + 2] -= dz * factor;
          }
        }
    }
    positions.needsUpdate = true;
  };
}

import {objectFit, phantomGrid, liquidGlassGrid, cinematicScroll} from "./article-effects.js";
import { squareFunctions, squareFragment, bulgeFunctions } from "./ported.js";
// Card-space coordinates are measured in viewport heights. One unit of travel
// moves a gallery by one card. Each effect owns its layout and shader changes.
const full = (s) => ({ w: s.aspect, h: 1 });
const strip = (s) => ({ x: s.offset * 0.82, w: 0.75, h: 0.78 });
const grid = (s) => {
  const col = s.slot % 7,
    row = Math.floor(s.slot / 7);
  return {
    x: (col - 3 - s.phase) * 0.49,
    y: (row - 2) * 0.36,
    w: 0.46,
    h: 0.33,
  };
};
const single = (layout, fragment = "", vertex = "") => ({
  layout,
  fragment,
  vertex,
  count: 1,
});
const gallery = (layout, vertex = "", fragment = "", count = 11) => ({
  layout,
  vertex,
  fragment,
  count,
});
export const effects = {
  MotionHover: single(
    (s) => ({
      x: (s.mx - 0.5) * s.aspect * 0.6,
      y: (s.my - 0.5) * 0.6,
      w: 0.72,
      h: 0.64,
    }),
    "color.r = sampleA(q+vec2(.016*(mouse.x-.5),0.)).r;",
    "p.x += (uv.y-.5)*(mouse.x-.5)*.24;",
  ),
  GooeyHover: single(
    full,
    "float edge=length((uv-mouse)*vec2(ratio,1.))+.045*sin(uv.x*32.+t)*sin(uv.y*29.-t); color=mix(color,sampleB(q),1.-smoothstep(.23,.29,edge));",
  ),
  CircularGallery: gallery((s) => {
    const a = s.offset * 0.39;
    return {
      x: 1.7 * Math.sin(a),
      y: 1.7 * (Math.cos(a) - 1),
      rz: -a,
      w: 0.58,
      h: 0.72,
    };
  }, "p.z=(sin(p.x*4.+t)*1.5+cos(p.y*2.+t)*1.5)*.055;"),
  InfiniteGallery: gallery(
    (s) => ({
      x: Math.sin(s.offset) * 0.24,
      y: s.offset * 0.73,
      w: 0.95,
      h: 0.66,
    }),
    "p.z-=.14*sin((offset+p.y)*3.14159+1.5708);",
  ),
  PhysicsCloth: { ...single((s) => ({ w: 1.05, h: 0.82 })), cloth: true },
  WebGLCarousel: gallery(
    (s) => {
      const open=Math.exp(-32*s.offset*s.offset);
      return {x:s.offset*.35,w:.29+(Math.min(s.aspect,1.6)-.29)*open,h:.72+.28*open,
        z:.02*open,focus:open};
    },
    "float ripple=sin(length(uv-.5)*15.+focus*12.); p.xy*=1.+ripple*.13*sin(focus*3.14159);",
  ),
  Bulge: {
    ...single(full, "color=sampleA(bulge(q,mouse));"),
    functions: bulgeFunctions,
  },
  EmergingImages: single(full, `
    vec2 cell=floor(uv*vec2(120.,120./ratio));
    float pattern=hash(cell);
    float front=phase*1.7-(1.-uv.y);
    float ink=smoothstep(0.,.42,front+pattern*.24-.24);
    float photo=smoothstep(.16,.58,front+pattern*.24-.24);
    color=mix(color,mix(vec4(1.,.22,.025,1.),sampleB(q),photo),ink);
  `),
  SdfLensBlur: single(full, `
    vec2 point=(uv-.5)*vec2(ratio,1.);
    vec2 corner=abs(point)-vec2(.27)+.035;
    float distanceToEdge=length(max(corner,0.))+min(max(corner.x,corner.y),0.)-.035;
    float lens=1.-smoothstep(.025,.33,length((uv-mouse)*vec2(ratio,1.)));
    float width=.005+.05*lens;
    float outline=1.-smoothstep(width,width+.002,abs(distanceToEdge));
    color=mix(color,vec4(1.),outline*(1.-.68*lens));
    color=mix(color,blur(q,.022),lens*.6);
  `),
  ProgressiveBlur: single(full, `
    float edge=smoothstep(.18,.51,abs(uv.y-.5));
    color=blur(q,.048*edge);
    color.rgb-=.023*edge*hash(gl_FragCoord.xy+floor(t*24.));
  `),
  ObjectFit: objectFit,
  ScrollGrain: gallery(
    (s) => ({ y: s.offset*.88, w:1.12, h:.82 }),
    "p.y+=sin(uv.x*3.14159)*clamp(speed,-5.,5.)*.018;",
    `float circle=1.-length((uv-mouse)*vec2(1.,1./ratio))*15.;
     float grain=hash(gl_FragCoord.xy+floor(t*20.))-.5;
     q+=vec2(circle*grain*.005)*min(1.,.14+abs(speed)*.32);
     color=sampleA(q);`,
  ),
  RotatingGallery: gallery(strip, `
    float local=clamp((phase-.22*uv.y)/.78,0.,1.);
    float eased=local<.5?16.*pow(local,5.):1.-.5*pow(2.-2.*local,5.);
    float angle=(floor(travel)+eased)*3.14159265;
    p.xz=mat2(cos(angle),-sin(angle),sin(angle),cos(angle))*p.xz;
  `),
  InteractiveGrid: gallery(
    (s) => {
      const g = grid(s);
      const dx = g.x - (s.mx - 0.5) * s.aspect,
        dy = g.y - (s.my - 0.5);
      return { ...g, z: 0.16 * Math.exp(-5 * (dx * dx + dy * dy)), focus: Math.min(1,2*Math.hypot(dx,dy)) };
    },
    "",
    "color.rgb=mix(color.rgb,vec3(dot(color.rgb,vec3(.2126,.7152,.0722))),focus);",
    35,
  ),
  ShaderRipple: single(full, `
    float dist=distance(uv,mouse)/length(max(mouse,1.-mouse));
    float wave=1.-smoothstep(phase-.08,phase+.02,dist);
    float brightness=dot(color.rgb,vec3(.299,.587,.114));
    color.rgb=mix(vec3(brightness),color.rgb,wave);
    color.rgb+=.025*sin(25.*dist-t*4.)*sin(phase*3.14159);
  `, "p.y+=.012*sin(-25.*distance(uv,mouse)+t*4.)*sin(phase*3.14159);"),
  DomCloth: gallery(
    strip,
    "p.z+=.12*sin(uv.x*6.+travel*3.)*sin(uv.y*3.14159);p.y+=.07*cos(uv.x*7.+t)*(1.-uv.y);",
  ),
  PhantomGrid: phantomGrid,
  DepthGallery: {
    ...gallery(s=>({
      x:(.38*Math.sin(s.index*2.4)+(s.mx-.5)*.095)*Math.min(s.aspect,1.6),
      y:.16*Math.cos(s.index*1.8)+(s.my-.5)*.065,
      z:-s.offset*1.05,ry:(s.mx-.5)*.09,rx:(.5-s.my)*.07,
      w:.55*s.imageAspect,h:.55,visible:s.offset>-.95,
    }), "", "color.rgb=mix(color.rgb,atmosphere,1.-exp(-max(depth,0.)*.32));"),
    atmospheric:true,
  },
  SquareLens: { ...single(full, squareFragment), functions: squareFunctions },
  CurveGallery: {
    ...gallery(s=>{
      const i=s.index*.66;
      return {x:Math.sin(i)*.76+.26*Math.cos(s.index*2.4),
        y:Math.sin(i*1.4)*.31+.17*Math.sin(s.index*1.7),z:-s.offset*.69,
        ry:.18*Math.cos(i),w:.48*s.imageAspect,h:.48,visible:s.offset>-.9};
    }, "", "float soft=smoothstep(.45,2.1,abs(depth-.68)); color=blur(q,.024*soft);",21),
    camera(camera,{travel}) {
      const a=travel*.66, ahead=(travel+1)*.66;
      camera.position.set(.76*Math.sin(a),.31*Math.sin(a*1.4),1.12);
      camera.lookAt(.76*Math.sin(ahead),.31*Math.sin(ahead*1.4),-.69);
    },
  },
  LiquidGlassGrid: liquidGlassGrid,
  ImageTube: {
    ...gallery(({slot,travel})=>{
      const row=Math.floor(slot/14), lap=Math.floor(travel);
      const absoluteRow=row+lap, phase=travel-lap;
      const angle=((slot%14)+(absoluteRow%2)*.5)*Math.PI/7+travel*(.30+.09*Math.cos(absoluteRow));
      return {x:.69*Math.sin(angle),z:.69*(Math.cos(angle)-1),
        y:(row-2-phase)*.38,ry:angle,w:.11,h:.16,textureIndex:absoluteRow*14+slot%14};
    },"","",84),background:"#ecebe8",
  },
  InfiniteCanvas: gallery(
    (s) => {
      const g = grid(s);
      return {
        ...g,
        x: g.x + (s.mx - 0.5) * 0.4,
        y: g.y + (s.my - 0.5) * 0.55,
        z: 0.1 * Math.sin(s.index * 13),
      };
    },
    "",
    "",
    35,
  ),
  CinematicScroll: cinematicScroll,
  KineticImages: {
    ...gallery(({slot,travel})=>{
      const row=Math.floor(slot/10)-2;
      const angle=(slot%10)*Math.PI/5 + travel*.6 + row*Math.PI/2;
      const x=.52*Math.sin(angle), y=row*.29;
      return {x:x*Math.cos(.15)+y*Math.sin(.15),y:y*Math.cos(.15)-x*Math.sin(.15),
        z:.52*(Math.cos(angle)-1),ry:angle,rz:-.15,w:.328,h:.235,textureIndex:slot};
    }, "float arc=p.x*.628; p.x=sin(arc)/.628; p.z+=.52*(cos(arc)-1.);",
      "",50), background:"#e9e5db",
  },
  Unwoven: {
    ...gallery(s=>({x:s.offset*.524,w:.465,h:.62})),
    ribbons:true, background:"#f7f6f3",
  },
  ExperimentalCarousel: gallery(strip, `
    float worldX=(modelMatrix*vec4(position,1.)).x;
    p.y+=.14*(cos(worldX*3.1)-1.);
    p.x-=sin(uv.y*3.14159)*clamp(speed,-4.,4.)*.075;
  `),
};

import * as THREE from "three";

// Sculpt a relief surface over an elliptical head, then sample it as points.
export function particlePortrait() {
  const positions = [], uv = [];
  const bump = (x, y, cx, cy, rx, ry) =>
    Math.exp(-(((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2));
  for (let row = 0; row < 88; row++) {
    const y = (row / 87) * 2 - 1;
    for (let col = 0; col < 64; col++) {
      const x = ((col + (row % 2) * 0.5) / 64) * 2 - 1;
      const shell = 1 - x * x - y * y;
      if (shell <= 0) continue;
      const eyes =
        bump(x, y, -0.35, 0.2, 0.2, 0.12) + bump(x, y, 0.35, 0.2, 0.2, 0.12);
      const nose = bump(x, y, 0, 0, 0.14, 0.36);
      const lips = bump(x, y, 0, -0.4, 0.34, 0.095);
      const z =
        Math.sqrt(shell) * 0.21 + nose * 0.1 - eyes * 0.052 + lips * 0.035;
      uv.push((x + 1) / 2, (y + 1) / 2);
      positions.push(x * (0.23 + 0.025 * y), y * 0.34, z);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uv, 2));
  const material = new THREE.ShaderMaterial({
    transparent: true, depthWrite: false,
    uniforms: {
      image: {value: null}, depthMap: {value: null}, hasDepth: {value: false},
      opacity: {value: 1}, pointSize: {value: 2}, cursor: {value: new THREE.Vector2(.5,.5)}
    },
    vertexShader: `
      uniform sampler2D image, depthMap;
      uniform bool hasDepth;
      uniform vec2 cursor;
      uniform float pointSize;
      varying vec3 tint;
      varying float mask;
      void main(){
        vec3 p=position;
        float relief=hasDepth ? texture2D(depthMap,uv).r : p.z;
        mask=hasDepth ? smoothstep(.01,.05,relief) : 1.;
        if(hasDepth) p.z=relief*.28;
        vec2 delta=uv-cursor;
        p.xy+=delta*.09*exp(-dot(delta,delta)*32.);
        tint=texture2D(image,uv).rgb;
        vec4 view=modelViewMatrix*vec4(p,1.);
        gl_Position=projectionMatrix*view;
        gl_PointSize=clamp(pointSize/-view.z,1.,8.);
      }`,
    fragmentShader: `
      uniform float opacity;
      varying vec3 tint;
      varying float mask;
      void main(){
        float radius=length(gl_PointCoord-.5);
        if(radius>.5 || mask<.01) discard;
        gl_FragColor=vec4(tint,opacity*mask*(1.-smoothstep(.32,.5,radius)));
        #include <colorspace_fragment>
      }`
  });
  const face = new THREE.Points(geometry, material);
  face.position.z = 0.22;
  return face;
}

'use client';
import { createElement as h, useEffect, useRef, useState } from "react";
import { effects } from "./effects.js";
import { mountScene } from "./scene.js";

function makeTemplate(name) {
  function Template(props) {
    const host = useRef(null),
      current = useRef(props);
    current.current = props;
    const [status, setStatus] = useState("");
    const inputs = JSON.stringify(props.images ?? []);
    const depthInputs = JSON.stringify(name === "PhantomGrid" ? props.depthMaps ?? [] : []);
    useEffect(() => {
      const sources = JSON.parse(inputs);
      if (!sources.length) {
        setStatus("Supply at least one image.");
        return;
      }
      setStatus("Loading images…");
      try {
        return mountScene(
          host.current,
          effects[name],
          sources,
          current,
          setStatus,
          JSON.parse(depthInputs),
        );
      } catch (error) {
        setStatus(error.message);
      }
    }, [inputs, depthInputs]);
    return h(
      "div",
      {
        className: props.className,
        style: {
          position: "relative",
          aspectRatio: "16/9",
          background: "#161819",
          ...props.style,
        },
      },
      h("div", {
        ref: host,
        role: "img",
        "aria-label": props.label ?? name,
        style: { position: "absolute", inset: 0, overflow: "hidden" },
      }),
      status &&
        h(
          "span",
          {
            role: "status",
            style: {
              position: "absolute",
              inset: 12,
              color: "white",
              pointerEvents: "none",
            },
          },
          status,
        ),
    );
  }
  Template.displayName = name;
  return Template;
}
export const templates = Object.fromEntries(
  Object.keys(effects).map((name) => [name, makeTemplate(name)]),
);
export const {
  MotionHover,
  GooeyHover,
  CircularGallery,
  InfiniteGallery,
  PhysicsCloth,
  WebGLCarousel,
  Bulge,
  EmergingImages,
  SdfLensBlur,
  ProgressiveBlur,
  ObjectFit,
  ScrollGrain,
  RotatingGallery,
  InteractiveGrid,
  ShaderRipple,
  DomCloth,
  PhantomGrid,
  DepthGallery,
  SquareLens,
  CurveGallery,
  LiquidGlassGrid,
  ImageTube,
  InfiniteCanvas,
  CinematicScroll,
  KineticImages,
  Unwoven,
  ExperimentalCarousel,
} = templates;

// Adapted upstream shaders. Attribution and license texts are in notices/.
export const squareFunctions = `
vec2 getCoverUv(vec2 uv, vec2 meshSize, vec2 textureSize) {
  vec2 meshRatio = vec2(meshSize.x / meshSize.y, meshSize.y / meshSize.x);
  vec2 textureRatio = vec2(textureSize.x / textureSize.y, textureSize.y / textureSize.x);
  vec2 resolutionRatio = vec2(
    min(meshRatio.x / textureRatio.x, 1.0),
    min(meshRatio.y / textureRatio.y, 1.0)
  );

  return (uv - 0.5) * resolutionRatio + 0.5;
}

// ---------------------------------------------------------------------------
// Applies a CC Lens-style radial distortion to UV coordinates.
// ---------------------------------------------------------------------------
float getCCLensScale(float distortion, float radius2) {
  if (distortion >= 0.0) {
    return 1.0 + distortion * radius2;
  }

  return 1.0 / (1.0 - distortion * radius2);
}

vec2 getCCLensUv(vec2 uv, vec2 resolution, float distortion) {
  vec2 centeredUv = uv - 0.5;
  vec2 aspectScale = vec2(resolution.x / resolution.y, 1.0);
  vec2 centeredPosition = centeredUv * aspectScale;

  float radius2 = dot(centeredPosition, centeredPosition);
  float lensScale = getCCLensScale(distortion, radius2);

  vec2 distortedPosition = centeredPosition * lensScale;
  vec2 distortedCenteredUv = distortedPosition / aspectScale;
  vec2 distortedUv = distortedCenteredUv + 0.5;
  vec2 distortionOffset = distortedUv - uv;

  return uv - distortionOffset;
}

// ---------------------------------------------------------------------------
// Generates a pseudo-random vec3 from a 3D input coordinate.
// ---------------------------------------------------------------------------
// <www.shadertoy.com/view/XsX3zB>
// by Nikita Miropolskiy
vec3 random3(vec3 c) {
  float j = 4096.0 * sin(dot(c, vec3(17.0, 59.4, 15.0)));
  vec3 r;

  r.z = fract(512.0 * j);
  j *= 0.125;
  r.x = fract(512.0 * j);
  j *= 0.125;
  r.y = fract(512.0 * j);

  return r - 0.5;
}
`;
export const squareFragment = `
{
  vec2 texture2Uv = getCoverUv(uv, vec2(ratio,1.), vec2(ratioB,1.));

  // Convert the square UV coordinates from the 0.0-to-1.0 range to the -1.0-to-1.0 range.
  vec2 uvSquare = uv * 2.0 - 1.0;

  // Offset the coordinates so the mouse position becomes the origin for the square test.
  uvSquare -= (mouse*2.-1.);

  // Calculate an aspect-ratio correction factor for determining the square's bounds.
  vec2 squareAspectScale = vec2(min((vec2(ratio,1.).y / vec2(ratio,1.).x), 1.0), min((vec2(ratio,1.).x / vec2(ratio,1.).y), 1.0));

  // Correct the test coordinates so the mask remains square.
  uvSquare /= squareAspectScale;

  float wave = sin(
    texture2Uv.y * 64.
    + t * 2.
  ) * .0018;
  texture2Uv.y += wave;
  texture2Uv += random3(
    vec3(texture2Uv * 220., t * 7.)
  ).x * .001;

  // Store half the square's side length so .37 can control its size.
  float squareHalfSize = .37;

  // Calculate the square's left edge.
  float left = -squareHalfSize;

  // Calculate the square's right edge.
  float right = squareHalfSize;

  // Calculate the square's bottom edge.
  float bottom = -squareHalfSize;

  // Calculate the square's top edge.
  float top = squareHalfSize;

  // Return 1.0 when uvSquare is inside the square and 0.0 when it is outside.
  float squareMask = step(left, uvSquare.x) * (1.0 - step(right, uvSquare.x)) * step(bottom, uvSquare.y) * (1.0 - step(top, uvSquare.y));

  // Convert uvSquare to the 0.0-to-1.0 range for the CC Lens distortion.
  vec2 squareUv = uvSquare / (squareHalfSize * 2.0) + 0.5;

  // Apply the CC Lens distortion inside the square.
  vec2 distortedSquareUv = getCCLensUv(squareUv, vec2(1.0), .58);

  // Calculate the square-local offset from the difference before and after distortion.
  vec2 squareLensOffset = distortedSquareUv - squareUv;

  // squareLensOffset is relative to the square. Adding it directly to uv would treat it as
  // relative to the entire mesh and make the distortion too large, so scale it by the square's
  // half-size and aspect-ratio correction factor to convert it to a mesh-relative offset.
  vec2 viewportLensOffset = squareLensOffset * squareHalfSize * squareAspectScale;

  // Convert the coordinates inside the square to UV coordinates for mapA.
  vec2 lensTexture1Uv = getCoverUv(uv + viewportLensOffset, vec2(ratio,1.), vec2(ratioA,1.));

  // Use the square's center as the origin so the RGB shift grows stronger toward the outside.
  vec2 rgbShiftDirection = (squareUv - 0.5) * 2.0;

  // Sample each RGB channel with a different UV offset to create color separation.
  float r = texture2D(mapA, lensTexture1Uv + rgbShiftDirection * .012).r;
  float g = texture2D(mapA, lensTexture1Uv + rgbShiftDirection * .003).g;
  float b = texture2D(mapA, lensTexture1Uv + rgbShiftDirection * -.007).b;

  // Recombine the shifted mapA channels to create the color inside the square.
  vec4 insideColor = vec4(r, g, b, 1.0);

  // Sample mapB for the color outside the square.
  vec4 outsideColor = texture2D(mapB, texture2Uv);

  // Blend the inside and outside colors according to the square mask.
  vec4 finalColor = mix(outsideColor, insideColor, squareMask);

  color = finalColor;
}
`;
export const bulgeFunctions = `
vec2 bulge(vec2 uv, vec2 center) {

  uv -= center; // center to mouse

  float dist = length(uv) / .34; // amount of distortion based on mouse pos
  float distPow = pow(dist, 4.); // exponential as you ar far from the mouse
  float strengthAmount = .72 / (1.0 + distPow); // strenght

  uv *= (1. - .68) + .68 * strengthAmount; // use .68 to smoothly reset/add effect

  uv += center; // reset pos

  return uv;
}
`;

import type { CSSProperties } from 'react';

export interface SlideshowProps {
  images: readonly string[];
  className?: string;
  style?: CSSProperties;
  label?: string;
  time?: number;
  secondsPerImage?: number;
  pointer?: readonly [number, number];
  playing?: boolean;
